findings.recommendation:
Add a characterization test that deliberately locks in the current mid-rune cut. Verified: with a 10-byte / 5-rune value in a width-4 column the cell renders as "\u03b1\xce~   " (7 bytes, 6 runes — note fmt's %-*s pads by RUNES, so the invalid byte counts as one):

func Test_printDataCell_multiByteIsByteSliced(t *testing.T) {
	// Characterization test: truncation is byte-based today (task 01 requires byte identity).
	// Converting printDataCell to rune-based slicing would change these bytes — that is a
	// separate, deliberate change, and this test must be updated with it, not silently.
	cfg := makeRenderConfig(6, 4)
	s := makeRenderResult(6, 1)
	s.Result.Values[0][0] = sql.NullString{String: "\u03b1\u03b1\u03b1\u03b1\u03b1", Valid: true} // 10 bytes, 5 runes

	var buf bytes.Buffer
	assert.NoError(t, printDataCell(&buf, s, cfg, 0, 0))
	assert.Equal(t, "\u03b1\xce~   ", buf.String(),
		"byte slicing cuts mid-rune at width-1 bytes; preserved verbatim by task 01")
}

